/*
 * A099267  Numbers generated by the golden sieve.
 * https://oeis.org/A099267
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy, nice
 * Formula:   a(n) = floor(n*phi + 2 - phi), phi = (1+sqrt(5))/2 We use the
 *            convergent 3524578/2178309 (phi ≈ 1.6180339887498948482…). The
 *            error |phi - 3524578/2178309| < 1/2178309² ≈ 2.1·10⁻¹³, so for
 *            any n up to about 10¹¹ the product difference is <0.5 and the
 *            integer part is exact. The computation uses onl...
 * Range:     u8 n <= 157, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n) {
    /* Convergent of phi: p = 3524578, q = 2178309 */
    const uint64_t P = 3524578UL;
    const uint64_t Q = 2178309UL;

    /* a(n) = floor( ((n-1)*P + 2*Q) / Q ) */
    /* Use 128‑bit intermediate to avoid overflow */
    unsigned __int128 prod = (unsigned __int128)(n - 1) * P;
    prod += (unsigned __int128)2 * Q;
    return (seq_t)(prod / Q);
}
